internal class GUPPriceEngineEcoResCategoryCache
{
    // Key = RecId of EcoResCategory.
    // Value = RecId of EcoResCategory.ParentCategory.
    private static Map categoryMap = null;

}

Method.Source:
/// <summary>
/// Check if one category belongs to another category (under or equal to that category).
/// </summary>
/// <param name = "_lineValue">The salesLine's category.</param>
/// <param name = "_conditionalValue">Pricing Rule's category.</param>
/// <returns>True if salesLines's category belongs to pricing rule's.</returns>
public static boolean belongsTo(int64 _lineValue, str _conditionalValue)
{
    if (_conditionalValue == null || _conditionalValue == "")
    {
        return true;
    }

    int64 _conditionalCategory = str2Int64(_conditionalValue);

    // Assume a salesLine cannot have 'unexist' category. Otherwise it always returns false.
    if (categoryMap == null || !categoryMap.exists(_lineValue))
    {
        GUPPriceEngineEcoResCategoryCache::initializeCache();
    }

    int64 lineCategory = _lineValue;

    // Compare salesLine's category and all its parents with contional value.
    // Until reaches top level (which has parentCategory = 0).
    while (lineCategory != 0)
    {
        if (lineCategory == _conditionalCategory)
        {
            return true;
        }
        lineCategory = categoryMap.lookup(lineCategory);
    }

    return false;
}

private static void initializeCache()
{
    Map categoryMapTemp = new Map(Types::Int64, Types::Int64);

    EcoResCategory category;
    while select category order by category.Level asc
    {
        categoryMapTemp.add(category.RecId, category.ParentCategory);
    }

    categoryMap = categoryMapTemp;
}
